-- All timestamps are TIMESTAMPTZ (stored as UTC). UUID PKs generated by the application or gen_random_uuid().

CREATE TABLE users (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email             VARCHAR(254) NOT NULL,
    password_hash     VARCHAR(100) NOT NULL,
    email_verified    BOOLEAN NOT NULL DEFAULT FALSE,
    date_of_birth     DATE NOT NULL,                 -- 18+ enforced at registration
    role              VARCHAR(20) NOT NULL DEFAULT 'USER',
    status            VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',  -- ACTIVE | SUSPENDED | DELETED
    suspended_reason  VARCHAR(500),
    onboarding_completed BOOLEAN NOT NULL DEFAULT FALSE,
    created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    updated_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_users_status CHECK (status IN ('ACTIVE','SUSPENDED','DELETED'))
);
CREATE UNIQUE INDEX uq_users_email_lower ON users (lower(email));

CREATE TABLE user_profiles (
    user_id          UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    display_name     VARCHAR(40) NOT NULL,
    country          CHAR(2),                         -- ISO 3166-1 alpha-2
    time_zone        VARCHAR(64),
    native_language  VARCHAR(10),                     -- BCP-47 / ISO 639-1
    english_level    VARCHAR(2) CHECK (english_level IN ('A1','A2','B1','B2','C1','C2')),
    learning_goals   TEXT[] NOT NULL DEFAULT '{}',
    interests        TEXT[] NOT NULL DEFAULT '{}',
    updated_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE user_preferences (
    user_id                 UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    match_similar_level     BOOLEAN NOT NULL DEFAULT TRUE,
    show_country            BOOLEAN NOT NULL DEFAULT TRUE,
    show_level              BOOLEAN NOT NULL DEFAULT TRUE,
    notify_email_reminders  BOOLEAN NOT NULL DEFAULT FALSE,
    notify_product_updates  BOOLEAN NOT NULL DEFAULT FALSE,
    updated_at              TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE refresh_tokens (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id       UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash    CHAR(64) NOT NULL UNIQUE,           -- SHA-256 hex of the opaque token
    family_id     UUID NOT NULL,                      -- rotation family; reuse of a revoked token revokes the family
    expires_at    TIMESTAMPTZ NOT NULL,
    revoked_at    TIMESTAMPTZ,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    user_agent    VARCHAR(255)
);
CREATE INDEX idx_refresh_tokens_user ON refresh_tokens (user_id);
CREATE INDEX idx_refresh_tokens_family ON refresh_tokens (family_id);

CREATE TABLE email_verification_tokens (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash  CHAR(64) NOT NULL UNIQUE,
    expires_at  TIMESTAMPTZ NOT NULL,
    used_at     TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_email_verification_user ON email_verification_tokens (user_id);

CREATE TABLE password_reset_tokens (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash  CHAR(64) NOT NULL UNIQUE,
    expires_at  TIMESTAMPTZ NOT NULL,
    used_at     TIMESTAMPTZ,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX idx_password_reset_user ON password_reset_tokens (user_id);

CREATE TABLE conversation_topics (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    slug        VARCHAR(50) NOT NULL UNIQUE,
    name        VARCHAR(80) NOT NULL,
    description VARCHAR(255),
    prompts     TEXT[] NOT NULL DEFAULT '{}',
    active      BOOLEAN NOT NULL DEFAULT TRUE,
    sort_order  INT NOT NULL DEFAULT 0
);

CREATE TABLE call_sessions (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    topic_id      UUID REFERENCES conversation_topics(id) ON DELETE SET NULL,
    status        VARCHAR(20) NOT NULL,   -- MATCH_FOUND|CONNECTING|CONNECTED|RECONNECTING|COMPLETED|FAILED|CANCELLED
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    connected_at  TIMESTAMPTZ,
    ended_at      TIMESTAMPTZ,
    duration_seconds INT,
    end_reason    VARCHAR(30),            -- ENDED | SKIPPED | DISCONNECTED | FAILED | TIMEOUT
    CONSTRAINT chk_call_status CHECK (status IN ('MATCH_FOUND','CONNECTING','CONNECTED','RECONNECTING','COMPLETED','FAILED','CANCELLED'))
);
CREATE INDEX idx_call_sessions_status ON call_sessions (status);

CREATE TABLE call_participants (
    call_id    UUID NOT NULL REFERENCES call_sessions(id) ON DELETE CASCADE,
    user_id    UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    joined_at  TIMESTAMPTZ,
    left_at    TIMESTAMPTZ,
    PRIMARY KEY (call_id, user_id)
);
CREATE INDEX idx_call_participants_user ON call_participants (user_id);

CREATE TABLE call_feedback (
    id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    call_id       UUID NOT NULL REFERENCES call_sessions(id) ON DELETE CASCADE,
    author_id     UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    rating        SMALLINT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    partner_was_respectful BOOLEAN,
    comment       VARCHAR(1000),
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT uq_feedback_call_author UNIQUE (call_id, author_id)
);

CREATE TABLE user_blocks (
    blocker_id  UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    blocked_id  UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (blocker_id, blocked_id),
    CONSTRAINT chk_no_self_block CHECK (blocker_id <> blocked_id)
);
CREATE INDEX idx_user_blocks_blocked ON user_blocks (blocked_id);

CREATE TABLE user_reports (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    reporter_id  UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    reported_id  UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    call_id      UUID REFERENCES call_sessions(id) ON DELETE SET NULL,
    reason       VARCHAR(30) NOT NULL,
    details      VARCHAR(1000),
    status       VARCHAR(20) NOT NULL DEFAULT 'OPEN',
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    CONSTRAINT chk_no_self_report CHECK (reporter_id <> reported_id)
);
CREATE INDEX idx_user_reports_reported ON user_reports (reported_id);

CREATE TABLE user_statistics (
    user_id                UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
    total_seconds          BIGINT NOT NULL DEFAULT 0,
    completed_calls        INT NOT NULL DEFAULT 0,
    current_streak_days    INT NOT NULL DEFAULT 0,
    longest_streak_days    INT NOT NULL DEFAULT 0,
    last_activity_date     DATE,
    updated_at             TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE daily_activity (
    user_id        UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    activity_date  DATE NOT NULL,           -- in UTC
    seconds        INT NOT NULL DEFAULT 0,
    calls          INT NOT NULL DEFAULT 0,
    PRIMARY KEY (user_id, activity_date)
);
